// Valida la identidad, busca la factura y arma los "hechos" con reglas. La clave no sale de este nodo.
// Contrato de salida: ok, motivo, id_transportista, hechos (valores reales), para_ia (lo único que verá la IA).
const form = $('Formulario').first().json;
const claveHash = $('Hashear clave').first().json.clave_hash;
const leer = n => $(n).all().map(i => i.json).filter(o => Object.keys(o).length)
  .map(o => Object.fromEntries(Object.entries(o).map(([k, v]) => [k, v == null ? '' : String(v)])));
const P = Object.fromEntries(leer('Leer parámetros').map(p => [p.parametro, p.valor]));
const trans = leer('Leer transportistas'), facturas = leer('Leer facturas'), viajes = leer('Leer viajes'),
      libro = leer('Leer libro'), reclamos = leer('Leer reclamos'), feriadosL = leer('Leer feriados');
const digitos = s => String(s ?? '').replace(/\D/g, '');
const norm = s => digitos(s).replace(/^0+/, '');
const hoy = P.fecha_ejecucion ? String(P.fecha_ejecucion).slice(0, 10) : $now.setZone('America/Argentina/Buenos_Aires').toISODate();

// 1 · Identidad (mismo método que WhatsApp: hash de "cuit:clave", 3 intentos y se bloquea)
const t = trans.find(x => digitos(x.cuit) === digitos(form['CUIT']));
let motivo = '', intento = null;
if (!t) motivo = 'cuit_no_registrado';
else if (t.estado_clave === 'Bloqueada') motivo = 'clave_bloqueada';
else if (t.estado_clave !== 'Activa') motivo = 'sin_clave';
else if (claveHash !== t.clave_hash) {
  const n = Number(t.intentos_fallidos || 0) + 1;
  motivo = n >= 3 ? 'clave_bloqueada' : 'clave_incorrecta';
  intento = { id_transportista: t.id_transportista, intentos_fallidos: n, estado_clave: n >= 3 ? 'Bloqueada' : 'Activa' };
}
if (motivo) return [{ json: { ok: false, motivo, intento,
  mensaje_final: 'No pudimos validar sus datos. Revise el CUIT y la clave. Si no tiene clave o la bloqueó, escríbanos por WhatsApp para generar una nueva.' } }];

// 2 · Factura: por número de comprobante o por remito/CTG, solo entre las del transportista validado
const propias = facturas.filter(f => f.id_transportista === t.id_transportista);
const ref = String(form['Comprobante o remito/CTG'] ?? '').trim(), nro = norm(ref);
// Se normaliza en el momento: sirve el comprobante completo (0003-00011036) o solo el número (11036)
let cand = propias.filter(f => norm(f.nro_comprobante) === nro || norm(String(f.nro_comprobante).split('-').pop()) === nro);
let via = 'comprobante', remito = '';
if (cand.length === 0) {
  const v = viajes.filter(v => norm(v.remito_ctg) === nro && propias.some(f => f.id_factura === v.id_factura));
  cand = [...new Set(v.map(x => x.id_factura))].map(id => propias.find(f => f.id_factura === id));
  if (v.length) { via = 'remito'; remito = v[0].remito_ctg; }
}
const f = cand.length === 1 ? cand[0] : null;

// 3 · Hechos por regla (la fecha estimada usa días hábiles y la hoja Feriados, igual que WhatsApp)
const feriados = new Set(feriadosL.map(x => String(x.fecha).slice(0, 10)));
const habil = d => ![0, 6].includes(d.getUTCDay()) && !feriados.has(d.toISOString().slice(0, 10));
const mover = (iso, n) => { const d = new Date(iso + 'T00:00:00Z'); const paso = n > 0 ? 1 : -1;
  while (n) { d.setUTCDate(d.getUTCDate() + paso); if (habil(d)) n -= paso; } return d.toISOString().slice(0, 10); };
const fmt = iso => iso ? String(iso).slice(0, 10).split('-').reverse().join('/') : '';
const textoCaso = { 'Carga no cargada en TMS': 'El viaje todavía no figura en el sistema de cargas y lo estamos gestionando.',
  'Consulta G4': 'La carga del viaje figura asociada a otra factura y la estamos revisando.',
  'Posible remito mal cargado': 'El remito del viaje figura cargado con una diferencia y lo estamos corrigiendo.',
  'Revisión manual': 'Un analista está revisando el viaje.' };

let estado = 'no_recibida', hechos = { comprobante: f ? f.nro_comprobante : ref };
if (cand.length > 1) estado = 'ambiguo';
else if (f) {
  const hasta = mover(f.fecha_vencimiento, 3), desde = mover(f.fecha_vencimiento, -1);
  const caso = libro.find(c => c.id_factura === f.id_factura && c.estado !== 'Resuelto');
  hechos = { ...hechos, fecha_vencimiento: fmt(f.fecha_vencimiento) };
  if (f.estado_pago === 'Pagada') { estado = 'pagada'; hechos.fecha_pago = fmt(f.fecha_pago); }
  else if (f.estado_pago === 'Rechazada') { estado = 'rechazada'; hechos.motivo_rechazo = f.motivo_rechazo; }
  else {
    estado = hoy <= hasta ? 'en_proceso_a_termino' : 'en_proceso_vencida';
    if (estado === 'en_proceso_a_termino') { hechos.pago_desde = fmt(hoy > desde ? hoy : desde); hechos.pago_hasta = fmt(hasta); }
    if (caso) hechos.situacion = textoCaso[caso.categoria] ?? textoCaso['Revisión manual'];
  }
}

// 4 · Enmascarar el texto libre: la IA no necesita números, mails ni CUIT para entender el pedido
const detalle = String(form['Detalle'] ?? '').slice(0, 600);
const enmascarado = detalle.replace(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g, '[mail oculto]')
  .replace(/\+?\d[\d\s.\/-]{5,}\d/g, '[número oculto]');

const previo = f && reclamos.find(r => r.estado === 'Abierto' && r.id_transportista === t.id_transportista && norm(r.nro_comprobante) === norm(f.nro_comprobante));
return [{ json: { ok: true, id_transportista: t.id_transportista, cuit: t.cuit, razon_social: t.razon_social,
  email_contacto: t.email_contacto, id_factura: f?.id_factura ?? '', remito_ctg: remito, via, estado, hechos,
  reclamo_previo: previo?.id_reclamo ?? '', cantidad_reclamos: reclamos.length, hoy, detalle,
  tipo_elegido: form['Qué necesita'] === 'Hacer un reclamo' ? 'reclamo' : 'consulta',
  para_ia: { tipo_elegido: form['Qué necesita'], detalle: enmascarado || '(sin detalle)', estado,
             marcadores: Object.keys(hechos).map(k => `{${k}}`).join(' ') } } }];

// Controla lo que devolvió la IA y completa los marcadores con los datos reales.
// Contrato: la IA devuelve intencion, tipo_reclamo, urgencia y respuesta. Este nodo agrega es_reclamo, tipo_final,
// id_reclamo, mensaje_final y control_respuesta. Si la IA falla o no pasa el control, se usa una plantilla fija.
const d = $('Validar y armar hechos').first().json;
const texto = String($json.text ?? '');
let r = null;
try { r = JSON.parse(texto.replace(/```json|```/g, '').trim()); } catch (e) { r = null; }

const problemas = [];
if (!r) problemas.push(texto ? 'respuesta no es JSON' : 'la IA no respondió');
const intencion = ['consulta', 'reclamo', 'otro'].includes(r?.intencion) ? r.intencion : 'consulta';
let resp = String(r?.respuesta ?? '');
const usados = [...resp.matchAll(/\{(\w+)\}/g)].map(m => m[1]);
const extra = usados.filter(k => !(k in d.hechos));
if (r && extra.length) problemas.push('marcadores no permitidos: ' + extra.join(', '));
const sinMarcas = resp.replace(/\{\w+\}/g, '');
if (r && /\d{2,}/.test(sinMarcas)) problemas.push('escribió números por su cuenta');
if (r && /\b(T|TMS|F|V)-\d/.test(sinMarcas)) problemas.push('menciona códigos internos');
const palabras = sinMarcas.split(/\s+/).filter(Boolean).length;
if (r && (palabras < 12 || palabras > 110)) problemas.push(`largo fuera de rango (${palabras} palabras)`);

const plantillas = {
  en_proceso_a_termino: 'Su factura {comprobante} está en proceso de pago. Vence el {fecha_vencimiento} y el pago se estima entre el {pago_desde} y el {pago_hasta}.',
  en_proceso_vencida: 'Su factura {comprobante} venció el {fecha_vencimiento} y todavía figura en proceso de pago.',
  pagada: 'Su factura {comprobante} figura pagada el {fecha_pago}.',
  rechazada: 'Su factura {comprobante} fue rechazada. Motivo: {motivo_rechazo}',
  no_recibida: 'No encontramos una factura con el número {comprobante} a su nombre. Revise el número o envíe la factura nuevamente.',
  ambiguo: 'Encontramos más de una factura con ese número. Ingrese el comprobante completo, con el punto de venta.' };
if (problemas.length) resp = plantillas[d.estado];
if (problemas.length && d.hechos.situacion) resp += ' {situacion}';

// El reclamo lo decide el código: lo pidió el transportista o la IA detectó que es un reclamo
const es_reclamo = (d.tipo_elegido === 'reclamo' || intencion === 'reclamo') && d.estado !== 'ambiguo';
const tipos = ['fuera_de_termino', 'factura_no_recibida', 'disconformidad', 'derivar_a_persona'];
const tipo_final = d.estado === 'no_recibida' ? 'factura_no_recibida' : d.estado === 'rechazada' ? 'disconformidad'
  : d.estado === 'en_proceso_vencida' ? 'fuera_de_termino' : tipos.includes(r?.tipo_reclamo) ? r.tipo_reclamo : 'derivar_a_persona';
const id_reclamo = !es_reclamo ? '' : d.reclamo_previo ||
  'R-' + d.hoy.slice(2).replace(/-/g, '') + '-F' + String(d.cantidad_reclamos + 1).padStart(3, '0');
if (es_reclamo) resp += d.reclamo_previo
  ? ' Ya tenemos un reclamo abierto por esta factura, el {id_reclamo}. Le vamos a responder por mail.'
  : ' Registramos su reclamo {id_reclamo}. Un analista lo va a revisar y le vamos a responder por mail.';

const valores = { ...d.hechos, id_reclamo };
const mensaje_final = resp.replace(/\{(\w+)\}/g, (m, k) => valores[k] ?? '').replace(/\.\s*\./g, '.').replace(/\s{2,}/g, ' ').trim();
return [{ json: { ...d, intencion, urgencia: r?.urgencia ?? '', es_reclamo, reclamo_nuevo: es_reclamo && !d.reclamo_previo,
  tipo_final, id_reclamo, respuesta_ia: String(r?.respuesta ?? texto).slice(0, 400), mensaje_final,
  control_respuesta: problemas.length ? 'Plantilla fija: ' + problemas.join('; ') : 'OK' } }];

